// Helpers behind components/InterpretPanel.tsx: the session-only key store
// (`tel_llm_key` in sessionStorage -- this tab, until it closes; never
// localStorage, never the server) and the per-status error copy for the LLM
// routes (docs/API.md "LLM results interpreter" error mapping).
import { ApiError } from '../api/client'
import type { LLMErrorDetail } from '../api/types'

export const LLM_KEY_STORAGE = 'tel_llm_key'

export const INTERPRET_FOOTER =
  'Generated by an LLM from this run’s recorded data. Fitness ≠ biological truth; this is a model result, not a clinical statement.'

export const PROPOSE_FOOTER =
  'Proposed by an LLM -- a hypothesis to test, not a result. Nothing has run yet: review the loaded parameters below, edit them if you like, then press "Run simulation" yourself. Not a dosing regimen or a fasting recommendation.'

export function readStoredKey(): string {
  try {
    return window.sessionStorage.getItem(LLM_KEY_STORAGE) ?? ''
  } catch {
    return ''
  }
}

export function storeKey(key: string): void {
  try {
    if (key) window.sessionStorage.setItem(LLM_KEY_STORAGE, key)
    else window.sessionStorage.removeItem(LLM_KEY_STORAGE)
  } catch {
    /* storage unavailable -- the key just lives in component state */
  }
}

function llmDetail(err: unknown): LLMErrorDetail | null {
  if (!(err instanceof ApiError)) return null
  const d = err.detail
  if (d && typeof d === 'object' && 'code' in d && 'message' in d) return d as LLMErrorDetail
  return null
}

/** Plain-language message per error class (docs/API.md error mapping). */
export function describeLLMError(err: unknown): string {
  const detail = llmDetail(err)
  if (err instanceof ApiError) {
    switch (err.status) {
      case 401:
        return detail?.code === 'llm_auth_failed'
          ? 'Anthropic rejected this API key. Check the key (it should start with sk-ant-) and try again.'
          : 'Your session has expired. Log in again.'
      case 403:
        return detail ? `Anthropic denied access for this key: ${detail.message}` : err.message
      case 429:
        return detail?.code === 'llm_rate_limited' && detail.message.startsWith('At most')
          ? `Rate limit: ${detail.message}`
          : 'Anthropic is rate-limiting this key (or its spend cap is reached). Wait a moment and try again.'
      case 422:
        if (detail?.code === 'llm_refusal') {
          return `The model declined to write this interpretation${detail.category ? ` (category: ${detail.category})` : ''}. Nothing was generated.`
        }
        if (detail?.code === 'llm_proposal_invalid') {
          return `The proposed protocol did not pass validation: ${detail.message}. Try rephrasing the goal, or propose again.`
        }
        return detail?.message ?? err.message
      case 502:
        return 'Could not reach Anthropic (network error or timeout). Your key was not stored; try again later.'
      default:
        return detail?.message ?? err.message
    }
  }
  return err instanceof Error ? err.message : 'Request failed.'
}
